364			return false
365		}
366		// Being able to mkdir a child is NOT enough: nsjail will write memory.max /
367		// pids.max / cpu.max into its own child cgroup, and those knobs exist only
368		// when the parent delegated the controllers (cgroup.subtree_control). On
369		// hosts where the controllers aren't delegated to children — e.g. the
370		// cgroup-v2 "no internal processes" rule blocks it because the server
371		// process sits directly in this cgroup — the child exposes no controllers,
372		// nsjail's cgroup write fails, and every worker crashes. Verify the child
373		// actually carries the controllers we need; if not, report no-delegate so
374		// the caller falls back to rlimit-only (functions run, just without the
375		// per-sandbox cgroup memory/pid caps) instead of crashing.
376		return childHasControllers(probe)
