155	// this platform has a different checksum than the running binary. The second
156	// return (known) is false when we can't determine it — no validation asset, the
157	// asset isn't listed, or any network/parse error — so callers fall back to the
158	// version-only decision rather than guessing. Best-effort: never fatal.
159	func remoteBuildDiffers(ctx context.Context, latest *selfupdate.Release, exePath string) (differs, known bool) {
