161			return false, false
162		}
163		localSHA, err := fileSHA256(exePath)
164		if err != nil {
165			return false, false
166		}
167		remoteSHA, err := remoteAssetSHA(ctx, latest.ValidationAssetURL, latest.AssetName)
168		if err != nil || remoteSHA == "" {
169			return false, false
170		}
171		return !strings.EqualFold(localSHA, remoteSHA), true
172	}
