189	// recorded for assetName (empty string if not present). Lines look like
190	// "<hex>␠␠<name>"; the name may carry a leading "*" (binary-mode marker).
191	func remoteAssetSHA(ctx context.Context, checksumsURL, assetName string) (string, error) {
192		reqCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
193		defer cancel()
194		req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, checksumsURL, nil)
195		if err != nil {
