197		}
198		resp, err := http.DefaultClient.Do(req)
199		if err != nil {
200			return "", err
201		}
202		defer resp.Body.Close()
203		if resp.StatusCode != http.StatusOK {
204			return "", fmt.Errorf("fetch checksums: status %d", resp.StatusCode)
205		}
206		return parseChecksums(resp.Body, assetName), nil
207	}
