210	func parseChecksums(r io.Reader, assetName string) string {
211		sc := bufio.NewScanner(r)
212		sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
213		for sc.Scan() {
214			fields := strings.Fields(sc.Text())
215			if len(fields) < 2 {
216				continue
217			}
218			name := strings.TrimPrefix(fields[len(fields)-1], "*")
219			if name == assetName {
220				return fields[0]
221			}
222		}
223		return ""
224	}
