227	// file at path. On Unix-likes this is an open-for-write probe; on Windows
228	// the running .exe is locked, but go-selfupdate handles that case via a
229	// rename-and-hide dance, so we accept any non-permission error.
230	func assertWritable(path string) error {
231		f, err := os.OpenFile(path, os.O_WRONLY, 0)
232		if err == nil {
