8	//     effective set.
9	//  2. **nftables packet filter**: every enabled rule's IPs/CIDRs go
10	//     into a dedicated nftables set and a chain that DROPs matching
11	//     egress packets.
12	//
13	// Source of truth is the `egress_blocklist` table — UI-driven, not
14	// config-file-driven. The Manager polls every 10s for table changes
15	// and applies them live.
16	package firewall
17	
18	import (
19		"context"
20		"errors"
21		"log/slog"
22		"net"
23		"strings"
24		"sync"
25		"time"
26	
27		"github.com/Harsh-2002/Orva/backend/internal/database"
28	)
29	
30	// Manager owns the firewall lifecycle. One instance per orvad process.
31	// Lives for the duration of the server; Stop() drains gracefully.
32	type Manager struct {
33		db      *database.Database
34		dataDir string // where the per-sandbox resolv.conf is written
35	
36		// Cached effective set of IPv4/IPv6 CIDRs derived from rules.
37		// Read by the API for /resolve introspection.
38		mu          sync.RWMutex
39		resolvedV4  []string // CIDRs ready for nft set
40		resolvedV6  []string
41		hostnameMap map[string][]string // rule.value → resolved IPs (for UI display)
42		lastError   string              // most recent apply or resolve error, surfaced by /firewall/status
43	
44		pollInterval    time.Duration
45		resolveInterval time.Duration
46	
47		stopCh chan struct{}
48		wg     sync.WaitGroup
49	}
50	
51	func NewManager(db *database.Database, dataDir string) *Manager {
52		return &Manager{
53			db:              db,
54			dataDir:         dataDir,
55			hostnameMap:     map[string][]string{},
56			pollInterval:    10 * time.Second,
57			resolveInterval: 5 * time.Minute,
58		}
59	}
60	
61	// Start kicks off the poll + resolve goroutines and applies the initial
62	// rule set. Errors during apply are logged but don't stop the manager —
63	// the API still works; nftables enforcement just won't be in place.
64	//
65	// In environments where nftables is unavailable (tests, hosts without
66	// NET_ADMIN, BSD), Start short-circuits: the API still answers, but no
67	// background goroutine runs. This avoids leaking polling goroutines
68	// across the test process lifetime.
69	func (m *Manager) Start(ctx context.Context) {
70		m.stopCh = make(chan struct{})
71	
72		// DNS (resolv.conf + hosts file) is independent of nftables — write
73		// both on every boot, even if packet filtering is disabled. Otherwise
74		// functions with network_mode=egress on hosts without nftables would
75		// lose operator-configured DNS resolvers and host overrides.
76		if m.dataDir != "" {
77			dnsCfg := LoadDNSConfig(m.db)
78			if err := WriteResolvConf(m.dataDir, dnsCfg); err != nil {
79				slog.Warn("firewall: initial resolv.conf write failed", "err", err)
80			}
81			if err := WriteHostsFile(m.dataDir, dnsCfg.Records); err != nil {
82				slog.Warn("firewall: initial hosts file write failed", "err", err)
83			}
84		}
85	
86		if !nftablesAvailable() {
87			m.setLastError("nftables unavailable: install the 'nftables' package, run 'modprobe nf_tables', and ensure the orva process has CAP_NET_ADMIN. Egress filtering is disabled until this is resolved; the per-function egress toggle still works (sandbox isolation only).")
88			slog.Warn("firewall: nftables unavailable — egress filtering disabled",
89				"hint", "install nftables, modprobe nf_tables, run with CAP_NET_ADMIN")
90			return
91		}
92	
93		// Initial apply on startup.
94		if err := m.refresh(); err != nil {
95			slog.Warn("firewall initial apply failed", "err", err)
96			m.setLastError(err.Error())
97		}
98	
99		m.wg.Add(1)
100		go m.pollLoop(ctx)
101	}
102	
103	func (m *Manager) Stop(ctx context.Context) error {
104		close(m.stopCh)
105		done := make(chan struct{})
106		go func() { m.wg.Wait(); close(done) }()
107		select {
108		case <-done:
109		case <-ctx.Done():
110			return ctx.Err()
111		}
112		// Best-effort cleanup of nftables state. Failures here are noise on
113		// shutdown so we just log.
114		if err := nftablesFlush(); err != nil {
115			slog.Debug("firewall flush on shutdown", "err", err)
116		}
117		return nil
118	}
119	
120	// pollLoop ticks the poll interval (DB changes) and the resolve
121	// interval (re-resolve hostnames). Combining them in one goroutine
122	// avoids races on m.resolvedV4/V6.
123	func (m *Manager) pollLoop(ctx context.Context) {
124		defer m.wg.Done()
125		pollT := time.NewTicker(m.pollInterval)
126		defer pollT.Stop()
127		resolveT := time.NewTicker(m.resolveInterval)
128		defer resolveT.Stop()
129	
130		for {
131			select {
132			case <-m.stopCh:
133				return
134			case <-ctx.Done():
135				return
136			case <-pollT.C:
137				if err := m.refresh(); err != nil {
138					slog.Warn("firewall refresh failed", "err", err)
139					m.setLastError(err.Error())
140				}
141			case <-resolveT.C:
142				if err := m.refresh(); err != nil {
143					slog.Warn("firewall resolve failed", "err", err)
144					m.setLastError(err.Error())
145				}
146			}
147		}
148	}
149	
150	// ForceRefresh is the API hook for "Force resolve now" in the UI.
151	// Returns whatever apply returned so the operator sees errors live.
152	func (m *Manager) ForceRefresh() error {
153		err := m.refresh()
154		if err != nil {
155			m.setLastError(err.Error())
156		}
157		return err
158	}
159	
160	// refresh: read enabled rules, expand hostnames to IPs, build set,
161	// apply nftables. Single goroutine path — no need to lock the apply.
162	func (m *Manager) refresh() error {
163		rules, err := m.db.ListEnabledBlocklistRules()
164		if err != nil {
165			return err
166		}
167	
168		v4, v6 := []string{}, []string{}
169		hostnameMap := map[string][]string{}
170	
171		for _, r := range rules {
172			switch r.RuleType {
173			case database.BlocklistTypeCIDR:
174				if isIPv6CIDR(r.Value) {
175					v6 = append(v6, r.Value)
176				} else {
177					v4 = append(v4, r.Value)
178				}
179			case database.BlocklistTypeHostname, database.BlocklistTypeWildcard:
180				ips := resolveHostnameSet(r.Value)
181				hostnameMap[r.Value] = ips
182				for _, ip := range ips {
183					if strings.Contains(ip, ":") {
184						v6 = append(v6, ip+"/128")
185					} else {
186						v4 = append(v4, ip+"/32")
187					}
188				}
189			}
190		}
191	
192		m.mu.Lock()
193		m.resolvedV4 = dedupe(v4)
194		m.resolvedV6 = dedupe(v6)
195		m.hostnameMap = hostnameMap
196		m.mu.Unlock()
197	
198		if err := nftablesApply(m.resolvedV4, m.resolvedV6); err != nil {
199			return err
200		}
201	
202		// Regenerate the per-sandbox resolv.conf + /etc/hosts alongside the
203		// nft rules. Both come from operator-driven settings; all three should
204		// re-apply on the same tick. Failure here is non-fatal — sandboxes
205		// fall back to whatever was last on disk (or the host's if we never
206		// wrote one).
207		if m.dataDir != "" {
208			dnsCfg := LoadDNSConfig(m.db)
209			if err := WriteResolvConf(m.dataDir, dnsCfg); err != nil {
210				slog.Warn("firewall: write resolv.conf failed", "err", err)
211			}
212			if err := WriteHostsFile(m.dataDir, dnsCfg.Records); err != nil {
213				slog.Warn("firewall: write hosts file failed", "err", err)
214			}
215		}
216	
217		m.setLastError("")
218		return nil
219	}
220	
221	// Snapshot returns a read-only view of the current effective set.
222	// Used by the /firewall/status endpoint and the UI's "currently
223	// resolving to" column.
224	type Snapshot struct {
225		IPv4         []string            `json:"ipv4"`
226		IPv6         []string            `json:"ipv6"`
227		HostnameMap  map[string][]string `json:"hostname_map"`
228		LastError    string              `json:"last_error,omitempty"`
229		NftablesAvail bool                `json:"nftables_available"`
230	}
231	
232	func (m *Manager) Snapshot() Snapshot {
233		m.mu.RLock()
234		defer m.mu.RUnlock()
235		out := Snapshot{
236			IPv4:          append([]string(nil), m.resolvedV4...),
237			IPv6:          append([]string(nil), m.resolvedV6...),
238			HostnameMap:   map[string][]string{},
239			LastError:     m.lastError,
240			NftablesAvail: nftablesAvailable(),
241		}
242		for k, v := range m.hostnameMap {
243			out.HostnameMap[k] = append([]string(nil), v...)
244		}
245		return out
246	}
247	
248	func (m *Manager) setLastError(s string) {
249		m.mu.Lock()
250		m.lastError = s
251		m.mu.Unlock()
252	}
253	
254	// resolveHostnameSet handles both exact hostnames and *.suffix wildcards.
255	// Wildcards can't be expanded (we don't enumerate every *.foo.com), so
256	// for a wildcard we resolve only the suffix's apex — best-effort. The
257	// nftables layer can't match by hostname, so wildcards primarily protect
258	// via the DNS layer (future work). Exact hostnames work fully.
259	func resolveHostnameSet(value string) []string {
260		target := value
261		if strings.HasPrefix(value, "*.") {
262			target = value[2:]
263		}
264		addrs, err := net.LookupHost(target)
265		if err != nil {
266			return nil
267		}
268		return addrs
269	}
270	
271	func isIPv6CIDR(s string) bool {
272		if !strings.Contains(s, "/") {
273			return strings.Contains(s, ":")
274		}
275		ip, _, err := net.ParseCIDR(s)
276		if err != nil {
277			return false
278		}
279		return ip.To4() == nil
280	}
281	
282	func dedupe(in []string) []string {
283		seen := map[string]bool{}
284		out := []string{}
285		for _, v := range in {
286			if seen[v] {
287				continue
288			}
289			seen[v] = true
290			out = append(out, v)
291		}
292		return out
293	}
294	
295	// ErrManagerClosed is returned from API calls after Stop().
296	var ErrManagerClosed = errors.New("firewall manager closed")
297

