	// on aarch64's unsupported list.
	prev := kafelRuntimeAliases
	kafelRuntimeAliases = append(append([]string(nil), prev...), "open")
	t.Cleanup(func() { kafelRuntimeAliases = prev })

	arm := buildSeccompPolicyForArch("strict", nil, nil, "arm64")
